"use client";

import * as DialogPrimitive from "@radix-ui/react-dialog";
import { createContext, useCallback, useContext, useLayoutEffect, useRef, useState } from "react";
import type { ComponentPropsWithoutRef, ReactNode } from "react";
import { AnimatePresence, motion, useReducedMotion } from "motion/react";
import type { Transition } from "motion/react";
import { X } from "lucide-react";
import { ESCAPE_LAYER_ATTRIBUTE, layerEscape } from "../lib/escape";
import { motionTokens } from "../lib/motion-tokens";
import { useReturnFocus } from "../lib/return-focus";
import styles from "./dialog.module.css";

/** Mirrors the open state so the content can stay mounted while it animates out, and retarget mid-flight if it is reopened or closed early. */
const OpenContext = createContext<boolean | null>(null);

export function Dialog({ open: openProp, defaultOpen = false, onOpenChange, ...props }: ComponentPropsWithoutRef<typeof DialogPrimitive.Root>) {
  const [uncontrolled, setUncontrolled] = useState(defaultOpen);
  const open = openProp ?? uncontrolled;
  const setOpen = useCallback((next: boolean) => { if (openProp === undefined) setUncontrolled(next); onOpenChange?.(next); }, [openProp, onOpenChange]);
  return <OpenContext.Provider value={open}><DialogPrimitive.Root {...props} open={open} onOpenChange={setOpen}/></OpenContext.Provider>;
}

export const DialogTrigger = DialogPrimitive.Trigger;
export const DialogClose = DialogPrimitive.Close;

export interface DialogContentProps extends ComponentPropsWithoutRef<typeof DialogPrimitive.Content> {
  title: string;
  description?: string;
  children: ReactNode;
}

const fade: Transition = { duration: motionTokens.duration.instant };
const leave: Transition = { duration: motionTokens.duration.fast, ease: [...motionTokens.ease.standard] };

/** When the title or description changes while open, the new copy rises in and the old copy leaves upward. */
function SwapText({ text }: { text: string }) {
  const reduced = useReducedMotion();
  return <AnimatePresence mode="popLayout" initial={false}>
    <motion.span key={text} className={styles.swap} initial={reduced ? false : { opacity: 0, y: "0.3em", filter: `blur(${motionTokens.blur.soft}px)` }} animate={{ opacity: 1, y: 0, filter: "blur(0px)" }} exit={reduced ? { opacity: 0, transition: { duration: 0 } } : { opacity: 0, y: "-0.3em", filter: `blur(${motionTokens.blur.subtle}px)`, transition: { duration: motionTokens.duration.fast, ease: [...motionTokens.ease.standard] } }} transition={{ duration: motionTokens.duration.standard, ease: [...motionTokens.ease.enter] }}>{text}</motion.span>
  </AnimatePresence>;
}

export function DialogContent({ title, description, children, className, onPointerDownOutside, onEscapeKeyDown, onOpenAutoFocus, onCloseAutoFocus, ...props }: DialogContentProps) {
  const open = useContext(OpenContext);
  // Closing puts focus back on what opened the dialog, Trigger or not (lib/return-focus.ts).
  const returnFocus = useReturnFocus(open, onOpenAutoFocus, onCloseAutoFocus);
  // Escape inside belongs to an open list, calendar or question first (lib/escape.ts); the next one closes the dialog.
  const escape = { [ESCAPE_LAYER_ATTRIBUTE]: "", onEscapeKeyDown: layerEscape(onEscapeKeyDown), ...returnFocus };
  const reduced = useReducedMotion();
  // When the open state last changed. Radix waits for the click before treating a press as outside, and a press on the trigger
  // while the dialog leaves reopens it first, so that press must not close it again.
  const change = useRef({ open, at: 0 });
  useLayoutEffect(() => { change.current = { open, at: performance.now() }; }, [open]);
  const pressOutside: DialogContentProps["onPointerDownOutside"] = event => {
    onPointerDownOutside?.(event);
    if (open !== null && (!change.current.open || event.detail.originalEvent.timeStamp < change.current.at)) event.preventDefault();
  };
  const classes = [styles.content, className].filter(Boolean).join(" ");
  const inner = <>
    <div className={styles.header}><div><DialogPrimitive.Title className={styles.title}><SwapText text={title}/></DialogPrimitive.Title>{description ? <DialogPrimitive.Description className={styles.description}><SwapText text={description}/></DialogPrimitive.Description> : null}</div><DialogPrimitive.Close className={styles.close} aria-label="Close dialog"><X size={16} strokeWidth={1.75} aria-hidden="true"/></DialogPrimitive.Close></div>
    <div className={styles.body}>{children}</div>
  </>;
  // Under a bare Radix root the open state is unknown here, so CSS keyframes keyed off data-state animate the layers instead.
  if (open === null) return <DialogPrimitive.Portal>
    <DialogPrimitive.Overlay className={`${styles.overlay} ${styles.keyframes}`}/>
    <DialogPrimitive.Content {...props} {...escape} onPointerDownOutside={pressOutside} className={`${classes} ${styles.keyframes}`}>{inner}</DialogPrimitive.Content>
  </DialogPrimitive.Portal>;
  // The overlay fades while the dialog rises 8px and scales up on a spring. Closing is shorter and quieter, and starts from wherever the entrance is.
  return <AnimatePresence>
    {open && <DialogPrimitive.Portal key="dialog" forceMount>
      <DialogPrimitive.Overlay asChild forceMount><motion.div className={styles.overlay} initial={{ opacity: 0 }} animate={{ opacity: 1 }} exit={{ opacity: 0, transition: reduced ? fade : leave }} transition={reduced ? fade : { duration: motionTokens.duration.standard, ease: [...motionTokens.ease.enter] }}/></DialogPrimitive.Overlay>
      <DialogPrimitive.Content {...props} {...escape} onPointerDownOutside={pressOutside} asChild forceMount>
        <motion.div className={classes} initial={reduced ? { opacity: 0 } : { opacity: 0, y: 8, scale: .96 }} animate={{ opacity: 1, y: 0, scale: 1 }} exit={reduced ? { opacity: 0, transition: fade } : { opacity: 0, y: 4, scale: .98, transition: leave }} transition={reduced ? fade : { default: motionTokens.spring.smooth, opacity: { duration: motionTokens.duration.fast, ease: [...motionTokens.ease.enter] } }}>{inner}</motion.div>
      </DialogPrimitive.Content>
    </DialogPrimitive.Portal>}
  </AnimatePresence>;
}

.overlay { position: fixed; inset: 0; z-index: var(--layer-overlay); background: var(--scrim); backdrop-filter: blur(7px); }
/* Centered with auto margins (like a native modal dialog) so transform stays free for the entrance spring. */
.content { position: fixed; z-index: var(--layer-dialog); inset: 0; width: min(calc(100vw - var(--space-block)), 440px); height: fit-content; max-height: calc(100vh - var(--space-block)); max-height: calc(100dvh - var(--space-block)); margin: auto; overflow: auto; border: 1px solid var(--border); border-radius: var(--radius-overlay); background: var(--surface-raised); color: var(--foreground); box-shadow: var(--shadow-floating); }
/* Motion animates both layers. Keyframes only run when DialogContent sits under a bare Radix root. */
.keyframes.overlay[data-state="open"] { animation: overlay-in var(--duration-standard) var(--ease-enter) both; }
.keyframes.overlay[data-state="closed"] { animation: overlay-out var(--duration-fast) var(--ease-standard) both; }
.keyframes.content[data-state="open"] { animation: content-fade-in var(--duration-fast) var(--ease-enter) both, content-rise-in var(--duration-spring) var(--ease-spring) both; }
.keyframes.content[data-state="closed"] { animation: content-out var(--duration-fast) var(--ease-standard) both; }
.content:focus { outline: none; }
/* While the layers leave, clicks pass through, so the trigger can reopen the dialog mid-exit. Radix sets pointer-events inline on the overlay. */
.overlay[data-state="closed"], .content[data-state="closed"] { pointer-events: none !important; }
.header { display: flex; justify-content: space-between; align-items: flex-start; gap: var(--space-comfort); padding: var(--space-section); border-bottom: 1px solid var(--border); }
.title { margin: 0; font-family: var(--font-body); font-size: var(--text-lg); font-weight: 500; letter-spacing: var(--tracking-body); line-height: var(--leading-body); }
.description { margin: var(--space-related) 0 0; color: var(--text-secondary); font-size: var(--text-sm); line-height: var(--leading-body); }
.title, .description { position: relative; overflow-wrap: anywhere; }
.swap { display: block; }
/* Line height sits on the text itself, so a page-level heading reset cannot shrink the title and pull the close button off its line. */
.title .swap { line-height: var(--leading-body); }
/* A compact icon button: quick press, spring release. The negative margin centres it on the title's first line. */
.close { flex: 0 0 auto; margin-block: calc((var(--text-lg) * var(--leading-body) - var(--space-block)) / 2); display: grid; place-items: center; width: var(--space-block); height: var(--space-block); border: 1px solid var(--border); border-radius: var(--radius-control); background: color-mix(in oklab, var(--surface-muted) 50%, transparent); color: var(--text-secondary); cursor: pointer; transition: background-color var(--duration-fast) var(--ease-standard), color var(--duration-fast) var(--ease-standard), transform var(--duration-spring) var(--ease-spring); }
@media (hover: hover) and (pointer: fine) { .close:hover { background: var(--surface-muted); color: var(--foreground); } }
.close:active { transform: scale(.96); transition: background-color var(--duration-fast) var(--ease-standard), color var(--duration-fast) var(--ease-standard), transform var(--duration-instant) var(--ease-standard); }
.body { padding: var(--space-section); font-size: var(--text-sm); line-height: var(--leading-body); }
@keyframes overlay-in { from { opacity: 0; } }
@keyframes overlay-out { to { opacity: 0; } }
@keyframes content-fade-in { from { opacity: 0; } }
@keyframes content-rise-in { from { transform: translateY(8px) scale(.96); } }
@keyframes content-out { to { opacity: 0; transform: translateY(4px) scale(.98); } }
@keyframes content-fade-out { to { opacity: 0; } }
@media (prefers-reduced-motion: reduce) {
  .keyframes.overlay[data-state="open"], .keyframes.content[data-state="open"] { animation: overlay-in var(--duration-instant) var(--ease-standard) both; }
  .keyframes.overlay[data-state="closed"] { animation: overlay-out var(--duration-instant) var(--ease-standard) both; }
  .keyframes.content[data-state="closed"] { animation: content-fade-out var(--duration-instant) var(--ease-standard) both; }
  .close, .close:active { transition: none; }
  .close:active { transform: none; }
}

/**
 * Escape inside a layer (Dialog, Drawer, BottomSheet, Popover) belongs to the control that has focus when that control
 * has something of its own to close: an open Combobox list, an open DatePicker calendar, an InlineEdit being edited, a
 * ConfirmMorph asking its question. Only the next Escape closes the layer.
 *
 * Radix closes its layers from a capture listener on the document, before the control's own key handler runs, so every
 * Silicon UI layer passes its `onEscapeKeyDown` through `layerEscape` (and marks its own panel with `data-escape-layer`, where
 * the search for an inner popup stops). Pages need nothing for this; their own `onEscapeKeyDown` still runs first and
 * can keep the layer open for reasons of its own with `event.preventDefault()`.
 */

/** Marks a layer's own panel (so it is never mistaken for a popup of a control inside it). */
export const ESCAPE_LAYER_ATTRIBUTE = "data-escape-layer";

/** Controls that close something of their own on Escape while focus is in them. */
const OWN_ESCAPE = [
  // Combobox with its list open (focus stays in its input).
  '[role="combobox"][aria-expanded="true"]',
  // DatePicker's trigger (or any popup button) while its panel is open.
  '[aria-haspopup="dialog"][aria-expanded="true"]',
  '[aria-haspopup="listbox"][aria-expanded="true"]',
  // InlineEdit while editing: Escape puts the saved text back.
  "[data-editing]",
].join(", ");

/** ConfirmMorph asking its question or showing a result (Escape returns it to rest). */
const MORPH_STATES = '[data-state="confirming"], [data-state="done"], [data-state="error"]';

/** True when Escape at `target` is handled by a control inside the layer, which closes its own part first. */
export function escapeBelongsInside(target: EventTarget | null): boolean {
  if (!(target instanceof Element)) return false;
  if (target.closest(OWN_ESCAPE)) return true;
  // A ConfirmMorph's root (focused while it works or shows a result) or one of its faces. A HoldToConfirm button also
  // says data-state="done", but it has no faces and no Escape of its own.
  const morph = target.closest(MORPH_STATES);
  if (morph?.querySelector("[data-face]")) return true;
  // A popup of a control (DatePicker's calendar is a dialog inside the layer); the layer's own panel is not one.
  const dialog = target.closest('[role="dialog"]');
  return !!dialog && !dialog.hasAttribute(ESCAPE_LAYER_ATTRIBUTE);
}

/**
 * The `onEscapeKeyDown` a Silicon UI layer gives Radix: the page's own handler first, then the layer stays open when the
 * Escape belongs to a control inside it.
 */
export function layerEscape<E extends KeyboardEvent>(own?: (event: E) => void): (event: E) => void {
  return event => {
    own?.(event);
    if (!event.defaultPrevented && escapeBelongsInside(event.target)) event.preventDefault();
  };
}

/**
 * Focus goes back to what opened a layer when it closes (WCAG 2.4.3), however it was opened.
 *
 * Radix's modal Dialog returns focus only to its own <Dialog.Trigger>. Most layers here open from controlled state (a
 * plain button, a menu item, a command, a key), so there is no Trigger and focus fell to <body> when they closed.
 * `useReturnFocus(open)` remembers what had focus when `open` turned true and hands the layer's content an
 * `onCloseAutoFocus` that puts focus back there:
 *
 * - it is captured in an insertion effect, which runs before anything in the layer can take focus (an `autoFocus`
 *   field is focused in the layout phase, Radix's FocusScope moves focus in a passive effect); under a bare Radix root,
 *   where `open` is unknown, `onOpenAutoFocus` captures it instead;
 * - the caller's own `onCloseAutoFocus` runs first, and one that calls `preventDefault()` keeps its own target;
 * - nothing remembered (focus was on <body>, or the element is gone): Radix's own behaviour, its Trigger if any;
 * - focus already moved on to something outside the layer while it left (a command opened another layer, a link was
 *   followed): it stays there.
 */
import { useInsertionEffect, useRef } from "react";

/** What has focus now, unless that is nothing in particular (<body>). */
function focusedElement(): HTMLElement | null {
  const active = typeof document === "undefined" ? null : document.activeElement;
  return active instanceof HTMLElement && active !== document.body ? active : null;
}

export interface ReturnFocusHandlers {
  onOpenAutoFocus: (event: Event) => void;
  onCloseAutoFocus: (event: Event) => void;
}

/**
 * `open`: the layer's open state (null or undefined when the caller cannot know it). `onOpenAutoFocus` /
 * `onCloseAutoFocus`: the caller's own handlers, composed (they run first).
 */
export function useReturnFocus(open: boolean | null | undefined, onOpenAutoFocus?: (event: Event) => void, onCloseAutoFocus?: (event: Event) => void): ReturnFocusHandlers {
  const opener = useRef<HTMLElement | null>(null);
  useInsertionEffect(() => {
    if (open) opener.current = focusedElement();
  }, [open]);
  return {
    onOpenAutoFocus(event) {
      if (open === null || open === undefined) opener.current = focusedElement();
      onOpenAutoFocus?.(event);
    },
    onCloseAutoFocus(event) {
      onCloseAutoFocus?.(event);
      const target = opener.current;
      opener.current = null;
      const layer = event.currentTarget instanceof Element ? event.currentTarget : null;
      if (event.defaultPrevented || !target?.isConnected || layer?.contains(target)) return;
      event.preventDefault();
      const active = document.activeElement;
      if (active && active !== document.body && !layer?.contains(active)) return;
      target.focus();
    },
  };
}
